1	/**
2	 * Common Ground — geometry pass 2 (CPU only, read-only).
3	 *
4	 * Follow-up to geometry-feasibility-probe.mts. Does NOT modify or re-run the
5	 * pass-1 artifacts. Two jobs:
6	 *
7	 *   PART A  convention audit: voxel coordinate frame, column-top ceiling,
8	 *           rendered-terrain occluder set, socket heights derived from real
9	 *           body/prop geometry, DDA vs. the pass-1 point-sampled ray, and the
10	 *           necessity of pass-1's near-field exemption.
11	 *   PART B  reference-aware graph search on the SAME endpoints for two route
12	 *           classes: an outer route that is entirely clear to a fixed
13	 *           reference, and a shorter route that is occluded to that same
14	 *           reference and needs exactly one occupied intermediate witness.
15	 *
16	 * Node/edge legality replicates agentSurfaceNavigation.ts::cellAt exactly
17	 * (face 'top', u=x, v=z, height=y) and is then CROSS-CHECKED against the
18	 * shipped planAgentSurfaceRoute on every edge of the reported routes plus a
19	 * bounded sample of rejected cells. Occluders are the rendered terrain cube
20	 * (|coord| <= radiusCells, the same gate the planner uses for clearance) plus
21	 * the hero trunk collider. No canopy, no fauna, no invented collision.
22	 *
23	 * Reproduce (esbuild bundle; vite-node trips the captures/ ENOSPC trap):
24	 *
25	 *   cd /home/thomasphillip/Projects/vox/main
26	 *   TM=$PWD/node_modules/three
27	 *   ./node_modules/.bin/esbuild \
28	 *     ../.codex/story-runs/2026-09-06-common-ground/geometry-pass2-probe.mts \
29	 *     --bundle --platform=node --format=esm --outfile=/tmp/cg-pass2.mjs \
30	 *     "--alias:three=$TM/build/three.module.js" \
31	 *     "--alias:three/examples/jsm/utils/BufferGeometryUtils.js=$TM/examples/jsm/utils/BufferGeometryUtils.js"
32	 *   node /tmp/cg-pass2.mjs > \
33	 *     ../.codex/story-runs/2026-09-06-common-ground/geometry-pass2.json
34	 */
35	import * as THREE from 'three';
36	import { createResolvedWorldGenerator } from '../../../main/src/utils/resolvedWorldGenerator.ts';
37	import { createStoryAnchorResolver, AUDIT_WORKER_GROUND_CLEARANCE } from '../../../main/src/story/world/storyAnchorResolver.ts';
38	import { STORY_SEED, STORY_PRIMARY_WORLD_ID, STORY_COORDINATE } from '../../../main/src/story/world/storyWorldIdentity.ts';
39	import { planAgentSurfaceRoute, type AgentSurfaceTerrainQuery } from '../../../main/src/utils/agentSurfaceNavigation.ts';
40	import { groundedSurfaceRouteLength } from '../../../main/src/utils/groundedSurfaceMotion.ts';
41	import { VOXEL_SCALE, voxelCoordToWorld, PLAYER_EYE_HEIGHT } from '../../../main/src/utils/cubeGravityConstants.ts';
42	import { buildTreeProfile } from '../../../main/src/utils/treeProfile.ts';
43	
44	const t0 = Date.now();
45	const PLANET_SIZE = 50;                                   // EfficientScene.tsx::planetSize
46	const RADIUS_CELLS = Math.max(1, Math.floor(PLANET_SIZE / VOXEL_SCALE)); // agentSurfaceNavigation.ts:312 => 25
47	const UP = new THREE.Vector3(0, 1, 0);
48	
49	// emergentStoryDirector.ts::moveAuditor — verbatim (unchanged from pass 1).
50	const WORKER_ROUTE_OPTIONS = {
51	  face: 'top' as const,
52	  differentFaceFallback: 'unreachable' as const,
53	  clearanceCells: 2,
54	  maxSlopeCells: 1,
55	  edgeMarginCells: 1,
56	  maxVisitedCells: 8192,
57	  waypointClearanceWorld: AUDIT_WORKER_GROUND_CLEARANCE,
58	  allowJetpackCrossing: false
59	};
60	const MAX_JETPACK_WATER_DEPTH_CELLS = 2; // resolvedOptions default, used by cellAt's scan window
61	
62	// chapter-story-treatment.md#proposed-bounded-trace-contract (unchanged, not relaxed)
63	const MAX_TRACE_POINTS = 128;
64	const MAX_TRACE_LENGTH = 120;
65	const SAMPLE_SPACING = 1.0;
66	const MIN_SAMPLE_SEPARATION = 0.25;
67	
68	const { generator } = createResolvedWorldGenerator({
69	  worldId: STORY_PRIMARY_WORLD_ID,
70	  seed: STORY_SEED,
71	  planetRadius: PLANET_SIZE / 2
72	});
73	const voxels = generator.getAllVoxelPositions();
74	const resolver = createStoryAnchorResolver({ generator, voxels });
75	const terrain: AgentSurfaceTerrainQuery = {
76	  isSolidVoxel: (x, y, z) => generator.shouldVoxelExist(x, y, z),
77	  isWaterVoxel: (x, y, z) => generator.isWaterVoxel(x, y, z),
78	  isHazardousVoxel: (x, y, z) => generator.generateBlockForPosition(x, y, z) === 'lava'
79	};
80	const v3 = (v: THREE.Vector3) => ({ x: +v.x.toFixed(3), y: +v.y.toFixed(3), z: +v.z.toFixed(3) });
81	const r2 = (n: number) => +n.toFixed(2);
82	
83	const tree = resolver.getHeroTreePose(PLANET_SIZE, STORY_SEED);
84	const pond = resolver.getPondPose(PLANET_SIZE, STORY_SEED);
85	const relay = resolver.getWreckRelayPose(PLANET_SIZE, STORY_SEED);
86	if (!pond) throw new Error('pass2: no pond pose on the pinned story world');
87	const heroProfile = buildTreeProfile((STORY_SEED ^ 0xede9) >>> 0);
88	const TRUNK_HEIGHT = Math.max(heroProfile.trunkHeight, 7.2);   // HeroAppleTree.tsx:79
89	const TRUNK_HALF = 0.55;                                       // HeroAppleTree.tsx:190
90	// AuditWorker.tsx:63 (constant inlined; the .tsx pulls react-three-fiber, which
91	// this CPU-only probe must not bundle). Verified by reading the source.
92	const AUDIT_WORKER_BOOT_SOLE_Y = -0.05;
93	
94	// ---------------------------------------------------------------------------
95	// PART A — conventions, measured against the shipped functions
96	// ---------------------------------------------------------------------------
97	// A1. voxelCoordToWorld(x,y,z) = coord * VOXEL_SCALE  => voxel CENTRE.
98	//     Occupancy AABB is [c*S - S/2, c*S + S/2]; the exact inverse is round(w/S).
99	const a1 = (() => {
100	  const probe = voxelCoordToWorld(-13, 25, 11);
101	  const back = { x: Math.round(probe.x / VOXEL_SCALE), y: Math.round(probe.y / VOXEL_SCALE), z: Math.round(probe.z / VOXEL_SCALE) };
102	  return {
103	    convention: 'voxel coordinate maps to voxel CENTRE; occupancy AABB is centre +/- VOXEL_SCALE/2',
104	    sample: { coord: [-13, 25, 11], world: v3(probe), inverseRound: back },
105	    inverseIsExact: back.x === -13 && back.y === 25 && back.z === 11,
106	    groundedPoseOffsetAboveSupportCentre: AUDIT_WORKER_GROUND_CLEARANCE,
107	    groundedPoseOffsetAboveSupportTopFace: r2(AUDIT_WORKER_GROUND_CLEARANCE - VOXEL_SCALE / 2)
108	  };
109	})();
110	
111	// A2. Socket heights derived from REAL geometry, expressed above the grounded
112	//     pose (the pose planAgentSurfaceRoute emits: support centre + 1.05).
113	const SOCKETS = {
114	  // AuditWorker.tsx: torso group y=1.3, visor mesh y=+0.55 => 1.85 above the
115	  // model root; the root sits at the grounded pose, sole at pose-0.05.
116	  workerVisor: 1.85,
117	  // torso centre (chest-mounted instrument plate)
118	  workerChest: 1.30,
119	  // straight-held arms, mesh centre y = 1.3 - 0.05
120	  workerHand: 1.25,
121	  // shipped player eye offset above a grounded pose
122	  // (cubeGravityConstants.ts + story/autopilotInteractionGaze.test.ts)
123	  playerEye: PLAYER_EYE_HEIGHT,
124	  // pass-1 probe's unsourced value, kept only for the A/B comparison
125	  pass1Assumed: 1.6
126	};
127	const REFERENCE_SOCKET_CANDIDATES = [0.6, 1.0, PLAYER_EYE_HEIGHT, 1.85];
128	const ACTOR_SOCKET = SOCKETS.workerVisor;
129	const REFERENCE_SOCKET = 1.85; // primary: matches the visor plane, level sightline
130	
131	// A3. Column top: the planner scans h from RADIUS_CELLS down and treats a
132	//     support as exposed at h === RADIUS_CELLS. Pass 1 scanned to
133	//     floor(PLANET_SIZE/2)+6 = 31.
134	const PASS1_TOP_LIMIT = Math.floor(PLANET_SIZE / 2) + 6;
135	function shippedColumnTop(vx: number, vz: number): number | null {
136	  for (let h = RADIUS_CELLS; h >= 0; h--) {
137	    if (!terrain.isSolidVoxel(vx, h, vz)) continue;
138	    if (h < RADIUS_CELLS && terrain.isSolidVoxel(vx, h + 1, vz)) continue;
139	    return h;
140	  }
141	  return null;
142	}
143	function pass1ColumnTop(vx: number, vz: number): number | null {
144	  for (let y = PASS1_TOP_LIMIT; y >= 0; y--) if (terrain.isSolidVoxel(vx, y, vz)) return y;
145	  return null;
146	}
147	
148	// Node legality — replica of agentSurfaceNavigation.ts::cellAt for face 'top'.
149	interface Cell { u: number; v: number; h: number; world: THREE.Vector3 }
150	const cellCache = new Map<string, Cell | null>();
151	function cellAt(u: number, v: number): Cell | null {
152	  const key = `${u},${v}`;
153	  const hit = cellCache.get(key);
154	  if (hit !== undefined) return hit;
155	  const h = shippedColumnTop(u, v);
156	  let out: Cell | null = null;
157	  if (h !== null
158	    && h >= Math.max(Math.abs(u), Math.abs(v)) + WORKER_ROUTE_OPTIONS.edgeMarginCells
159	    && !terrain.isHazardousVoxel!(u, h, v)) {
160	    let bodyBlocked = false;
161	    let wet = terrain.isWaterVoxel(u, h, v);
162	    const scan = MAX_JETPACK_WATER_DEPTH_CELLS + WORKER_ROUTE_OPTIONS.clearanceCells;
163	    for (let lift = 1; lift <= scan; lift++) {
164	      const y = h + lift;
165	      const insideRendered = Math.max(Math.abs(u), Math.abs(y), Math.abs(v)) <= RADIUS_CELLS;
166	      const solid = insideRendered && terrain.isSolidVoxel(u, y, v);
167	      const hazard = insideRendered && terrain.isHazardousVoxel!(u, y, v);
168	      if (terrain.isWaterVoxel(u, y, v)) wet = true;
169	      if (lift <= WORKER_ROUTE_OPTIONS.clearanceCells && (solid || hazard)) bodyBlocked = true;
170	    }
171	    if (!wet && !bodyBlocked) {
172	      out = { u, v, h, world: voxelCoordToWorld(u, h, v).addScaledVector(UP, AUDIT_WORKER_GROUND_CLEARANCE) };
173	    }
174	  }
175	  cellCache.set(key, out);
176	  return out;
177	}
178	
179	// ---------------------------------------------------------------------------
180	// Line of sight — Amanatides & Woo DDA over voxel AABBs, rendered cube only,
181	// plus the hero trunk collider box. No canopy, no fauna, no new collision.
182	// ---------------------------------------------------------------------------
183	interface LosResult { clear: boolean; blockedBy: 'terrain' | 'trunk' | null; voxel: [number, number, number] | null; distance: number; selfColumnHit: boolean }
184	function trunkHit(a: THREE.Vector3, b: THREE.Vector3): boolean {
185	  const t = tree.position;
186	  const lo = { x: t.x - TRUNK_HALF, y: t.y, z: t.z - TRUNK_HALF };
187	  const hi = { x: t.x + TRUNK_HALF, y: t.y + TRUNK_HEIGHT, z: t.z + TRUNK_HALF };
188	  const d = { x: b.x - a.x, y: b.y - a.y, z: b.z - a.z };
189	  let tmin = 0, tmax = 1;
190	  for (const ax of ['x', 'y', 'z'] as const) {
191	    const dd = d[ax];
192	    if (Math.abs(dd) < 1e-9) { if (a[ax] < lo[ax] || a[ax] > hi[ax]) return false; continue; }
193	    let t1 = (lo[ax] - a[ax]) / dd;
194	    let t2 = (hi[ax] - a[ax]) / dd;
195	    if (t1 > t2) { const s = t1; t1 = t2; t2 = s; }
196	    tmin = Math.max(tmin, t1);
197	    tmax = Math.min(tmax, t2);
198	    if (tmin > tmax) return false;
199	  }
200	  return true;
201	}
202	function los(a: THREE.Vector3, b: THREE.Vector3, exempt: Array<[number, number, number]> = []): LosResult {
203	  const distance = a.distanceTo(b);
204	  const dir = b.clone().sub(a);
205	  const half = VOXEL_SCALE / 2;
206	  let cx = Math.round(a.x / VOXEL_SCALE), cy = Math.round(a.y / VOXEL_SCALE), cz = Math.round(a.z / VOXEL_SCALE);
207	  const ex = Math.round(b.x / VOXEL_SCALE), ey = Math.round(b.y / VOXEL_SCALE), ez = Math.round(b.z / VOXEL_SCALE);
208	  const step = { x: Math.sign(dir.x), y: Math.sign(dir.y), z: Math.sign(dir.z) };
209	  const tDelta = { x: 0, y: 0, z: 0 } as Record<'x' | 'y' | 'z', number>;
210	  const tMax = { x: Infinity, y: Infinity, z: Infinity } as Record<'x' | 'y' | 'z', number>;
211	  const centres = { x: cx * VOXEL_SCALE, y: cy * VOXEL_SCALE, z: cz * VOXEL_SCALE };
212	  for (const ax of ['x', 'y', 'z'] as const) {
213	    const dd = dir[ax];
214	    if (dd === 0) continue;
215	    tDelta[ax] = Math.abs(VOXEL_SCALE / dd);
216	    const boundary = centres[ax] + (dd > 0 ? half : -half);
217	    tMax[ax] = (boundary - a[ax]) / dd;
218	  }
219	  let selfColumnHit = false;
220	  const isExempt = (x: number, y: number, z: number) =>
221	    exempt.some(e => e[0] === x && e[1] === y && e[2] === z);
222	  for (let guard = 0; guard < 512; guard++) {
223	    const inside = Math.max(Math.abs(cx), Math.abs(cy), Math.abs(cz)) <= RADIUS_CELLS;
224	    const solid = inside && terrain.isSolidVoxel(cx, cy, cz);
225	    if (solid) {
226	      if (isExempt(cx, cy, cz)) selfColumnHit = true;
227	      else return { clear: false, blockedBy: 'terrain', voxel: [cx, cy, cz], distance: r2(distance), selfColumnHit };
228	    }
229	    if (cx === ex && cy === ey && cz === ez) break;
230	    const m = tMax.x <= tMax.y ? (tMax.x <= tMax.z ? 'x' : 'z') : (tMax.y <= tMax.z ? 'y' : 'z');
231	    if (tMax[m] > 1) break;
232	    if (m === 'x') cx += step.x; else if (m === 'y') cy += step.y; else cz += step.z;
233	    tMax[m] += tDelta[m];
234	  }
235	  if (trunkHit(a, b)) return { clear: false, blockedBy: 'trunk', voxel: null, distance: r2(distance), selfColumnHit };
236	  return { clear: true, blockedBy: null, voxel: null, distance: r2(distance), selfColumnHit };
237	}
238	// pass-1 ray: 0.35-unit point sampling, no rendered-cube gate, endpoints excluded
239	function pass1Ray(a: THREE.Vector3, b: THREE.Vector3): boolean {
240	  const steps = Math.ceil(a.distanceTo(b) / 0.35);
241	  for (let i = 1; i < steps; i++) {
242	    const p = a.clone().lerp(b, i / steps);
243	    if (terrain.isSolidVoxel(Math.round(p.x / VOXEL_SCALE), Math.round(p.y / VOXEL_SCALE), Math.round(p.z / VOXEL_SCALE))) return true;
244	  }
245	  return false;
246	}
247	
248	/** Socket above a grounded pose, with its own support column exempted. */
249	function socket(cell: Cell, height: number) {
250	  return {
251	    point: cell.world.clone().addScaledVector(UP, height),
252	    exempt: [[cell.u, cell.h, cell.v], [cell.u, cell.h + 1, cell.v]] as Array<[number, number, number]>
253	  };
254	}
255	function witness(from: Cell, fromHeight: number, to: Cell, toHeight: number): LosResult {
256	  const a = socket(from, fromHeight);
257	  const b = socket(to, toHeight);
258	  return los(a.point, b.point, [...a.exempt, ...b.exempt]);
259	}
260	
261	// ---------------------------------------------------------------------------
262	// Trace sampling rule — IDENTICAL to pass 1. No decimation, no relaxed caps.
263	// ---------------------------------------------------------------------------
264	function traceSamples(points: THREE.Vector3[]): THREE.Vector3[] {
265	  const out: THREE.Vector3[] = [];
266	  if (!points.length) return out;
267	  out.push(points[0].clone());
268	  let last = points[0].clone();
269	  let lastHeading: THREE.Vector3 | null = null;
270	  for (let i = 1; i < points.length; i++) {
271	    const a = points[i - 1];
272	    const b = points[i];
273	    const segLen = a.distanceTo(b);
274	    const heading = b.clone().sub(a).setY(0).normalize();
275	    const turned = lastHeading ? heading.dot(lastHeading) < Math.cos(Math.PI / 12) : false;
276	    let travelled = 0;
277	    while (travelled < segLen) {
278	      const need = turned && last.distanceTo(a) >= MIN_SAMPLE_SEPARATION ? MIN_SAMPLE_SEPARATION : SAMPLE_SPACING;
279	      const remaining = need - last.distanceTo(a.clone().lerp(b, travelled / segLen));
280	      travelled += Math.max(0.05, remaining);
281	      if (travelled > segLen) break;
282	      const p = a.clone().lerp(b, travelled / segLen);
283	      if (p.distanceTo(last) >= MIN_SAMPLE_SEPARATION) { out.push(p); last = p.clone(); }
284	    }
285	    lastHeading = heading;
286	  }
287	  const end = points[points.length - 1];
288	  if (end.distanceTo(last) > 1e-3) out.push(end.clone());
289	  return out;
290	}
291	
292	// ---------------------------------------------------------------------------
293	// PART B — reference-aware graph search
294	// ---------------------------------------------------------------------------
295	// Endpoints: identical for both route classes, and identical to pass 1.
296	function nearestDryCell(seed: THREE.Vector3, maxRadius = 8, minDistance = 0): Cell | null {
297	  const su = Math.round(seed.x / VOXEL_SCALE);
298	  const sv = Math.round(seed.z / VOXEL_SCALE);
299	  for (let r = 0; r <= maxRadius; r++) {
300	    let best: { d: number; c: Cell } | null = null;
301	    for (let du = -r; du <= r; du++) for (let dv = -r; dv <= r; dv++) {
302	      if (Math.max(Math.abs(du), Math.abs(dv)) !== r) continue;
303	      const c = cellAt(su + du, sv + dv);
304	      if (!c) continue;
305	      const d = c.world.distanceTo(seed);
306	      if (d < minDistance) continue;
307	      if (!best || d < best.d) best = { d, c };
308	    }
309	    if (best) return best.c;
310	  }
311	  return null;
312	}
313	const startCell = nearestDryCell(tree.position, 8, 3);   // >=3 units clear of the trunk box
314	const endCell = nearestDryCell(pond.shore);
315	const relayCell = nearestDryCell(relay.position);
316	if (!startCell || !endCell || !relayCell) throw new Error('pass2: endpoints unresolved');
317	
318	// Bounded node field around the corridor.
319	const MARGIN_CELLS = 14;
320	const uLo = Math.min(startCell.u, endCell.u) - MARGIN_CELLS;
321	const uHi = Math.max(startCell.u, endCell.u) + MARGIN_CELLS;
322	const vLo = Math.min(startCell.v, endCell.v) - MARGIN_CELLS;
323	const vHi = Math.max(startCell.v, endCell.v) + MARGIN_CELLS;
324	const nodes: Cell[] = [];
325	const nodeIndex = new Map<string, number>();
326	for (let u = uLo; u <= uHi; u++) for (let v = vLo; v <= vHi; v++) {
327	  const c = cellAt(u, v);
328	  if (!c) continue;
329	  nodeIndex.set(`${u},${v}`, nodes.length);
330	  nodes.push(c);
331	}
332	const NEIGHBORS: Array<[number, number]> = [[1, 0], [-1, 0], [0, 1], [0, -1]];
333	function edges(i: number): number[] {
334	  const c = nodes[i];
335	  const out: number[] = [];
336	  for (const [du, dv] of NEIGHBORS) {
337	    const j = nodeIndex.get(`${c.u + du},${c.v + dv}`);
338	    if (j === undefined) continue;
339	    if (Math.abs(nodes[j].h - c.h) > WORKER_ROUTE_OPTIONS.maxSlopeCells) continue;
340	    out.push(j);
341	  }
342	  return out;
343	}
344	/** Deterministic BFS (unit-cost 4-grid; cost order matches the planner's g). */
345	function bfs(fromIdx: number, toIdx: number, allowed: Uint8Array | null): Cell[] | null {
346	  const prev = new Int32Array(nodes.length).fill(-1);
347	  const seen = new Uint8Array(nodes.length);
348	  if (allowed && (!allowed[fromIdx] || !allowed[toIdx])) return null;
349	  const queue = [fromIdx];
350	  seen[fromIdx] = 1;
351	  for (let qi = 0; qi < queue.length; qi++) {
352	    const cur = queue[qi];
353	    if (cur === toIdx) {
354	      const path: Cell[] = [];
355	      for (let n = cur; n !== -1; n = prev[n]) path.push(nodes[n]);
356	      return path.reverse();
357	    }
358	    for (const nx of edges(cur)) {
359	      if (seen[nx]) continue;
360	      if (allowed && !allowed[nx]) continue;
361	      seen[nx] = 1;
362	      prev[nx] = cur;
363	      queue.push(nx);
364	    }
365	  }
366	  return null;
367	}
368	const startIdx = nodeIndex.get(`${startCell.u},${startCell.v}`)!;
369	const endIdx = nodeIndex.get(`${endCell.u},${endCell.v}`)!;
370	
371	// DEFECT GUARD: agentSurfaceNavigation only knows terrain voxels. The hero
372	// trunk is a separate CuboidCollider, so the grid can hand back a cell whose
373	// standing pose lies INSIDE the trunk box. Ban those cells and report them.
374	const trunkAllowed = new Uint8Array(nodes.length).fill(1);
375	const trunkFootprintCells: Array<Record<string, unknown>> = [];
376	for (let i = 0; i < nodes.length; i++) {
377	  const c = nodes[i];
378	  const insideXZ = Math.abs(c.world.x - tree.position.x) <= TRUNK_HALF && Math.abs(c.world.z - tree.position.z) <= TRUNK_HALF;
379	  const underTrunkTop = c.world.y <= tree.position.y + TRUNK_HEIGHT;
380	  if (insideXZ && underTrunkTop) {
381	    trunkAllowed[i] = 0;
382	    trunkFootprintCells.push({ cell: [c.u, c.v], supportVoxel: [c.u, c.h, c.v], world: v3(c.world) });
383	  }
384	}
385	function andTrunk(mask: Uint8Array | null): Uint8Array {
386	  const out = new Uint8Array(nodes.length);
387	  for (let i = 0; i < nodes.length; i++) out[i] = (mask ? mask[i] : 1) && trunkAllowed[i] ? 1 : 0;
388	  return out;
389	}
390	
391	function corners(path: Cell[]): THREE.Vector3[] {
392	  return path.map(c => c.world.clone());
393	}
394	function measure(path: Cell[]) {
395	  const pts = corners(path);
396	  const length = groundedSurfaceRouteLength(pts.map(position => ({ position })), UP);
397	  const samples = traceSamples(pts);
398	  return { pts, length, samples };
399	}
400	function evaluate(path: Cell[], ref: Cell, refHeight = REFERENCE_SOCKET) {
401	  const { pts, length, samples } = measure(path);
402	  const refSocket = socket(ref, refHeight);
403	  const lines = samples.map(p => {
404	    const a = p.clone().addScaledVector(UP, ACTOR_SOCKET);
405	    const su = Math.round(p.x / VOXEL_SCALE), sv = Math.round(p.z / VOXEL_SCALE);
406	    const sh = shippedColumnTop(su, sv);
407	    const exempt: Array<[number, number, number]> = sh === null ? [] : [[su, sh, sv], [su, sh + 1, sv]];
408	    return los(a, refSocket.point, [...exempt, ...refSocket.exempt]);
409	  });
410	  const blocked = lines.map((l, i) => ({ l, i })).filter(x => !x.l.clear);
411	  return {
412	    waypointCount: pts.length,
413	    walkedLength: r2(length),
414	    lengthWithinBudget: length <= MAX_TRACE_LENGTH,
415	    traceSampleCount: samples.length,
416	    pointsWithinBudget: samples.length <= MAX_TRACE_POINTS,
417	    witnessClearSamples: samples.length - blocked.length,
418	    witnessBlockedSamples: blocked.length,
419	    blockedByTerrain: blocked.filter(b => b.l.blockedBy === 'terrain').length,
420	    blockedByTrunk: blocked.filter(b => b.l.blockedBy === 'trunk').length,
421	    selfColumnHits: lines.filter(l => l.selfColumnHit).length,
422	    maxWitnessDistance: r2(Math.max(...lines.map(l => l.distance))),
423	    firstBlockedSample: blocked.length ? { index: blocked[0].i, position: v3(samples[blocked[0].i]) } : null,
424	    lastBlockedSample: blocked.length ? { index: blocked[blocked.length - 1].i, position: v3(samples[blocked[blocked.length - 1].i]) } : null,
425	    _samples: samples,
426	    _blockedIdx: blocked.map(b => b.i),
427	    _path: path
428	  };
429	}
430	
431	// Fixed reference candidates: dry columns in the established tree/inspection
432	// corridor. Bounded, deterministic, reported rather than authored.
433	const refCandidates = nodes
434	  .filter(c => {
435	    const d = c.world.distanceTo(tree.position);
436	    return d >= 3 && d <= 24;
437	  })
438	  .sort((a, b) => (a.world.distanceTo(tree.position) - b.world.distanceTo(tree.position)) || (a.u - b.u) || (a.v - b.v))
439	  .slice(0, 96);
440	
441	const shortPathTrunkTraversable = bfs(startIdx, endIdx, null);
442	const shortPath = bfs(startIdx, endIdx, trunkAllowed);
443	if (!shortPath || !shortPathTrunkTraversable) throw new Error('pass2: no route between the arena endpoints');
444	const shortPathCrossesTrunk = shortPathTrunkTraversable.some(c =>
445	  Math.abs(c.world.x - tree.position.x) <= TRUNK_HALF && Math.abs(c.world.z - tree.position.z) <= TRUNK_HALF);
446	
447	interface Solution {
448	  reference: Cell;
449	  outer: ReturnType<typeof evaluate>;
450	  shorter: ReturnType<typeof evaluate>;
451	  clearNodeCount: number;
452	}
453	const solutions: Solution[] = [];
454	const refRejections = { startOrEndNotClearToReference: 0, noClearChain: 0, outerOverLength: 0, outerOverPoints: 0, outerNotLonger: 0, shorterNotOccluded: 0 };
455	for (const ref of refCandidates) {
456	  const allowed = new Uint8Array(nodes.length);
457	  let clearCount = 0;
458	  for (let i = 0; i < nodes.length; i++) {
459	    if (witness(nodes[i], ACTOR_SOCKET, ref, REFERENCE_SOCKET).clear) { allowed[i] = 1; clearCount++; }
460	  }
461	  if (!allowed[startIdx] || !allowed[endIdx]) { refRejections.startOrEndNotClearToReference++; continue; }
462	  const outerPath = bfs(startIdx, endIdx, andTrunk(allowed));
463	  if (!outerPath) { refRejections.noClearChain++; continue; }
464	  const outer = evaluate(outerPath, ref);
465	  const shorter = evaluate(shortPath, ref);
466	  if (!outer.lengthWithinBudget) { refRejections.outerOverLength++; continue; }
467	  if (!outer.pointsWithinBudget) { refRejections.outerOverPoints++; continue; }
468	  if (outer.walkedLength <= shorter.walkedLength) { refRejections.outerNotLonger++; continue; }
469	  if (shorter.witnessBlockedSamples === 0) { refRejections.shorterNotOccluded++; continue; }
470	  solutions.push({ reference: ref, outer, shorter, clearNodeCount: clearCount });
471	}
472	// Deterministic ordering: shortest qualifying outer route first.
473	solutions.sort((a, b) => (a.outer.walkedLength - b.outer.walkedLength)
474	  || (a.reference.u - b.reference.u) || (a.reference.v - b.reference.v));
475	
476	// --- intermediate witness for the shorter route's occluded bend -------------
477	const witnessRejections = { tooCloseToFixedReference: 0, cannotSeeOccludedSpan: 0, unreachable: 0, accepted: 0 };
478	function findWitnesses(sol: Solution, limit = 3) {
479	  const blockedPts = sol.shorter._blockedIdx.map(i => sol.shorter._samples[i]);
480	  if (!blockedPts.length) return [];
481	  const results: Array<Record<string, unknown>> = [];
482	  for (const w of nodes) {
483	    if (w.world.distanceTo(sol.reference.world) < 4) { witnessRejections.tooCloseToFixedReference++; continue; } // must be a DISTINCT reference
484	    const wSock = socket(w, REFERENCE_SOCKET);
485	    let ok = true;
486	    let maxD = 0;
487	    for (const p of blockedPts) {
488	      const a = p.clone().addScaledVector(UP, ACTOR_SOCKET);
489	      const su = Math.round(p.x / VOXEL_SCALE), sv = Math.round(p.z / VOXEL_SCALE);
490	      const sh = shippedColumnTop(su, sv);
491	      const exempt: Array<[number, number, number]> = sh === null ? [] : [[su, sh, sv], [su, sh + 1, sv]];
492	      const line = los(a, wSock.point, [...exempt, ...wSock.exempt]);
493	      if (!line.clear) { ok = false; break; }
494	      maxD = Math.max(maxD, line.distance);
495	    }
496	    if (!ok) { witnessRejections.cannotSeeOccludedSpan++; continue; }
497	    // The player must be able to stand there and offer it: reachable from the
498	    // shorter route under the same worker-legal grid.
499	    const wIdx = nodeIndex.get(`${w.u},${w.v}`)!;
500	    const reach = bfs(startIdx, wIdx, trunkAllowed);
501	    if (!reach) { witnessRejections.unreachable++; continue; }
502	    witnessRejections.accepted++;
503	    const { length: reachLen } = measure(reach);
504	    const minToTrace = Math.min(...blockedPts.map(p => w.world.distanceTo(p)));
505	    results.push({
506	      position: v3(w.world),
507	      supportVoxel: [w.u, w.h, w.v],
508	      maxLineOfReferenceDistance: r2(maxD),
509	      minDistanceToOccludedSpan: r2(minToTrace),
510	      distanceToFixedReference: r2(w.world.distanceTo(sol.reference.world)),
511	      walkedDistanceFromStartReference: r2(reachLen),
512	      coversAllOccludedSamples: true,
513	      _score: maxD
514	    });
515	  }
516	  results.sort((a, b) => (a.minDistanceToOccludedSpan as number) - (b.minDistanceToOccludedSpan as number));
517	  const clean = (r: Record<string, unknown>) => { const { _score, ...rest } = r; return rest; };
518	  const nearest = results[0];
519	  const farthest = results[results.length - 1];
520	  const mid = results[Math.floor(results.length / 2)];
521	  // deterministic: a clearly-positioned witness = the one standing OFF the
522	  // occluded span (>= 4 units) with the shortest walk from the start reference
523	  const offSpan = results.filter(r => (r.minDistanceToOccludedSpan as number) >= 4)
524	    .sort((a, b) => (a.walkedDistanceFromStartReference as number) - (b.walkedDistanceFromStartReference as number));
525	  return {
526	    acceptedCount: results.length,
527	    nearest: nearest ? clean(nearest) : null,
528	    median: mid ? clean(mid) : null,
529	    farthest: farthest ? clean(farthest) : null,
530	    clearlyPositionedOffSpan: offSpan.length ? clean(offSpan[0]) : null,
531	    firstN: results.slice(0, limit).map(clean)
532	  };
533	}
534	
535	// --- shipped-planner cross validation --------------------------------------
536	function planLeg(a: THREE.Vector3, b: THREE.Vector3) {
537	  return planAgentSurfaceRoute(terrain, PLANET_SIZE, a, b, WORKER_ROUTE_OPTIONS);
538	}
539	function validateEdges(path: Cell[]) {
540	  let ok = 0; const failures: unknown[] = [];
541	  for (let i = 1; i < path.length; i++) {
542	    const r = planLeg(path[i - 1].world, path[i].world);
543	    const endsAtGoal = r.waypoints.length > 0 && r.waypoints[r.waypoints.length - 1].distanceTo(path[i].world) < 1e-3;
544	    if (r.mode === 'walk' && r.reason === 'dry-surface-path' && endsAtGoal) ok++;
545	    else if (r.mode === 'direct' && r.reason === 'already-at-resolved-goal') ok++;
546	    else if (failures.length < 5) failures.push({ from: v3(path[i - 1].world), to: v3(path[i].world), mode: r.mode, reason: r.reason });
547	  }
548	  return { edges: path.length - 1, plannerAccepted: ok, failures };
549	}
550	/** Straight runs between direction changes, re-planned by the shipped planner. */
551	function validateCornerLegs(path: Cell[]) {
552	  const cornerIdx = [0];
553	  for (let i = 1; i < path.length - 1; i++) {
554	    const a = path[i - 1], b = path[i], c = path[i + 1];
555	    if ((b.u - a.u) !== (c.u - b.u) || (b.v - a.v) !== (c.v - b.v)) cornerIdx.push(i);
556	  }
557	  cornerIdx.push(path.length - 1);
558	  let ok = 0; const failures: unknown[] = [];
559	  for (let i = 1; i < cornerIdx.length; i++) {
560	    const a = path[cornerIdx[i - 1]], b = path[cornerIdx[i]];
561	    const r = planLeg(a.world, b.world);
562	    const straightSame = r.mode === 'walk' && r.waypoints.length === Math.abs(b.u - a.u) + Math.abs(b.v - a.v) + 1;
563	    if (straightSame) ok++; else if (failures.length < 5) failures.push({ from: v3(a.world), to: v3(b.world), mode: r.mode, reason: r.reason, waypoints: r.waypoints.length });
564	  }
565	  return { legs: cornerIdx.length - 1, plannerAgreedStraight: ok, failures };
566	}
567	
568	// Bounded check that the replica's REJECTIONS agree with the shipped planner:
569	// sample rejected cells adjacent to an accepted one and confirm the planner
570	// will not resolve a walk that terminates on them.
571	function validateRejections(limit = 60) {
572	  let checked = 0, agreed = 0; const disagreements: unknown[] = [];
573	  for (let u = uLo; u <= uHi && checked < limit; u += 3) {
574	    for (let v = vLo; v <= vHi && checked < limit; v += 3) {
575	      if (cellAt(u, v)) continue;
576	      let neighbour: Cell | null = null;
577	      for (const [du, dv] of NEIGHBORS) { const c = cellAt(u + du, v + dv); if (c) { neighbour = c; break; } }
578	      if (!neighbour) continue;
579	      const target = voxelCoordToWorld(u, pass1ColumnTop(u, v) ?? neighbour.h, v).addScaledVector(UP, AUDIT_WORKER_GROUND_CLEARANCE);
580	      const r = planLeg(neighbour.world, target);
581	      const landed = r.waypoints.length ? r.waypoints[r.waypoints.length - 1] : null;
582	      const landedOnRejected = !!landed && Math.round(landed.x / VOXEL_SCALE) === u && Math.round(landed.z / VOXEL_SCALE) === v;
583	      checked++;
584	      if (!landedOnRejected) agreed++;
585	      else if (disagreements.length < 5) disagreements.push({ cell: [u, v], mode: r.mode, reason: r.reason, landed: v3(landed!) });
586	    }
587	  }
588	  return { checked, agreed, disagreements };
589	}
590	
591	// --- A/B: pass-1 ray & socket conventions vs. this pass ---------------------
592	function conventionDelta(sol: Solution | null) {
593	  const sample = (sol ? sol.outer._samples : traceSamples(corners(shortPath))).filter((_, i) => i % 2 === 0);
594	  const ref = sol ? sol.reference : startCell;
595	  const refPoint = socket(ref, REFERENCE_SOCKET).point;
596	  let ddaBlocked = 0, pass1Blocked = 0, disagree = 0, outsideCubeOnly = 0, selfColumn = 0;
597	  for (const p of sample) {
598	    const a = p.clone().addScaledVector(UP, ACTOR_SOCKET);
599	    const su = Math.round(p.x / VOXEL_SCALE), sv = Math.round(p.z / VOXEL_SCALE);
600	    const sh = shippedColumnTop(su, sv);
601	    const exempt: Array<[number, number, number]> = sh === null ? [] : [[su, sh, sv], [su, sh + 1, sv]];
602	    const d = los(a, refPoint, [...exempt, ...socket(ref, REFERENCE_SOCKET).exempt]);
603	    const p1a = p.clone().addScaledVector(UP, SOCKETS.pass1Assumed);
604	    const p1b = ref.world.clone().addScaledVector(UP, SOCKETS.pass1Assumed);
605	    const p1 = pass1Ray(p1a, p1b);
606	    if (!d.clear) ddaBlocked++;
607	    if (p1) pass1Blocked++;
608	    if (d.selfColumnHit) selfColumn++;
609	    if ((!d.clear) !== p1) disagree++;
610	    if (d.blockedBy === 'terrain' && d.voxel && Math.max(Math.abs(d.voxel[0]), Math.abs(d.voxel[1]), Math.abs(d.voxel[2])) > RADIUS_CELLS) outsideCubeOnly++;
611	  }
612	  return { comparedLines: sample.length, ddaBlocked, pass1PointSampledBlocked: pass1Blocked, disagreements: disagree, blockersOutsideRenderedCube: outsideCubeOnly, linesHittingOwnSupportColumn: selfColumn };
613	}
614	
615	// Column-top ceiling delta over the node field.
616	const topDelta = (() => {
617	  let differing = 0, columns = 0;
618	  for (let u = uLo; u <= uHi; u++) for (let v = vLo; v <= vHi; v++) {
619	    const s = shippedColumnTop(u, v);
620	    const p = pass1ColumnTop(u, v);
621	    if (s === null && p === null) continue;
622	    columns++;
623	    if (s !== p) differing++;
624	  }
625	  return { columnsCompared: columns, columnsWhereCeilingDiffers: differing, pass1ScanCeiling: PASS1_TOP_LIMIT, shippedScanCeiling: RADIUS_CELLS };
626	})();
627	
628	const solutionTable = solutions.map(s => ({
629	  fixedReference: v3(s.reference.world),
630	  supportVoxel: [s.reference.u, s.reference.h, s.reference.v],
631	  distanceToTree: r2(s.reference.world.distanceTo(tree.position)),
632	  referenceClearNodes: s.clearNodeCount,
633	  outerLength: s.outer.walkedLength,
634	  outerSamples: s.outer.traceSampleCount,
635	  outerBlocked: s.outer.witnessBlockedSamples,
636	  shorterLength: s.shorter.walkedLength,
637	  shorterSamples: s.shorter.traceSampleCount,
638	  shorterBlocked: s.shorter.witnessBlockedSamples,
639	  shorterBlockedByTerrain: s.shorter.blockedByTerrain,
640	  shorterBlockedByTrunk: s.shorter.blockedByTrunk,
641	  detourExtraUnits: r2(s.outer.walkedLength - s.shorter.walkedLength)
642	}));
643	// Terrain occlusion is the legible class (pass 1 measured the 1.1-unit trunk as
644	// a sub-degree knife edge). Report the best terrain-occluded candidate too.
645	const terrainOccluded = solutions.filter(s => s.shorter.blockedByTerrain > 0);
646	const renderedCeilingCheck = (() => {
647	  let columnsWithLogicalVoxelsAboveCube = 0;
648	  const examples: unknown[] = [];
649	  for (let u = uLo; u <= uHi; u++) for (let v = vLo; v <= vHi; v++) {
650	    const p1 = pass1ColumnTop(u, v);
651	    if (p1 !== null && p1 > RADIUS_CELLS) {
652	      columnsWithLogicalVoxelsAboveCube++;
653	      if (examples.length < 5) examples.push({ cell: [u, v], pass1Top: p1, shippedTop: shippedColumnTop(u, v), solidAt26: terrain.isSolidVoxel(u, 26, v), solidAt27: terrain.isSolidVoxel(u, 27, v) });
654	    }
655	  }
656	  return {
657	    note: 'generator.shouldVoxelExist is not clipped to the rendered cube; agentSurfaceNavigation gates it with insideRenderedTerrain, pass 1\'s ray did not',
658	    columnsWithLogicalVoxelsAboveCube,
659	    examples
660	  };
661	})();
662	const best = solutions[0] ?? null;
663	const bestTerrain = terrainOccluded[0] ?? null;
664	const witnesses = best ? findWitnesses(best) : [];
665	const witnessesTerrain = bestTerrain && bestTerrain !== best ? findWitnesses(bestTerrain) : witnesses;
666	// Socket sensitivity for the reported solution (does the answer survive other
667	// plausible socket heights?).
668	const socketSensitivity = best
669	  ? REFERENCE_SOCKET_CANDIDATES.map(hRef => {
670	    const outer = evaluate(best.outer._path, best.reference, hRef);
671	    const shorter = evaluate(shortPath, best.reference, hRef);
672	    return {
673	      referenceSocketHeight: hRef,
674	      actorSocketHeight: ACTOR_SOCKET,
675	      outerFullyClear: outer.witnessBlockedSamples === 0,
676	      outerBlockedSamples: outer.witnessBlockedSamples,
677	      shorterBlockedSamples: shorter.witnessBlockedSamples,
678	      distinctionHolds: outer.witnessBlockedSamples === 0 && shorter.witnessBlockedSamples > 0
679	    };
680	  })
681	  : [];
682	
683	const strip = (e: ReturnType<typeof evaluate> | null) => {
684	  if (!e) return null;
685	  const { _samples, _blockedIdx, _path, ...rest } = e;
686	  return { ...rest, occludedSampleIndices: _blockedIdx.slice(0, 40), occludedSampleCount: _blockedIdx.length };
687	};
688	
689	const report = {
690	  probe: 'common-ground geometry pass 2 (reference-aware)',
691	  generatedAt: new Date().toISOString(),
692	  supersedes: null,
693	  relationToPass1: 'independent follow-up; pass-1 artifacts unmodified',
694	  derivation: 'source-derived (pristine procedural terrain; no live voxel edits, no render, no GPU, no server)',
695	  world: {
696	    planetSize: PLANET_SIZE, radiusCells: RADIUS_CELLS, storyCoordinate: STORY_COORDINATE,
697	    storySeed: STORY_SEED, worldId: STORY_PRIMARY_WORLD_ID, voxelScale: VOXEL_SCALE, voxelCount: voxels.length
698	  },
699	  workerRouteOptions: WORKER_ROUTE_OPTIONS,
700	  traceContract: { maxPoints: MAX_TRACE_POINTS, maxLengthUnits: MAX_TRACE_LENGTH, sampleSpacing: SAMPLE_SPACING, minSeparation: MIN_SAMPLE_SEPARATION, capsRelaxed: false, cornersDecimated: false },
701	  conventionAudit: {
702	    voxelFrame: a1,
703	    socketHeightsAboveGroundedPose: { ...SOCKETS, bootSoleLocalY: AUDIT_WORKER_BOOT_SOLE_Y, chosenActorSocket: ACTOR_SOCKET, chosenReferenceSocket: REFERENCE_SOCKET, referenceSocketCandidates: REFERENCE_SOCKET_CANDIDATES },
704	    columnTopCeiling: topDelta,
705	    occluderSet: {
706	      terrain: 'solid voxels with max(|x|,|y|,|z|) <= radiusCells (the planner\'s insideRenderedTerrain gate)',
707	      structure: 'hero trunk CuboidCollider 1.1 x 1.1 x ' + r2(TRUNK_HEIGHT) + ' (HeroAppleTree.tsx:190)',
708	      excluded: ['canopy instances (no collider)', 'fauna/grass', 'player-built StructureField pieces (not procedural)', 'logical voxels outside the rendered cube']
709	    },
710	    rayCasting: { method: 'Amanatides-Woo DDA over voxel AABBs (centre +/- 1.0)', pass1Method: '0.35-unit point sampling, round() to voxel, no rendered-cube gate' },
711	    nearFieldHandling: { pass1: 'blanket 3.0-unit horizontal exemption, counted separately', pass2: 'exempt only the two endpoint support columns (support voxel and the voxel above it)' }
712	  },
713	  endpoints: {
714	    sharedByBothRouteClasses: true,
715	    startReferenceAtTree: { world: v3(startCell.world), supportVoxel: [startCell.u, startCell.h, startCell.v], distanceToTrunkAxis: r2(startCell.world.distanceTo(tree.position)) },
716	    endReferenceOnPondShore: { world: v3(endCell.world), supportVoxel: [endCell.u, endCell.h, endCell.v] },
717	    approachReferenceNearRelay: { world: v3(relayCell.world), supportVoxel: [relayCell.u, relayCell.h, relayCell.v] },
718	    straightDistance: r2(startCell.world.distanceTo(endCell.world)),
719	    heroTree: { position: v3(tree.position), trunkHeight: r2(TRUNK_HEIGHT), trunkColliderHalfExtentXZ: TRUNK_HALF },
720	    pondShore: v3(pond.shore)
721	  },
722	  plannerTrunkBlindness: {
723	    finding: 'planAgentSurfaceRoute knows terrain voxels only; the hero trunk CuboidCollider is invisible to it',
724	    trunkFootprintCellsInsideNodeField: trunkFootprintCells,
725	    unrestrictedShortestRouteWalksThroughTrunk: shortPathCrossesTrunk,
726	    consequence: 'without this guard the shorter route\'s only witness break is the actor standing INSIDE the trunk box, which no reference can see and which is not a legible occlusion',
727	    guardApplied: 'cells whose grounded pose lies inside the trunk XZ box below the trunk top are banned from both route classes'
728	  },
729	  nodeField: { boundsCells: { uLo, uHi, vLo, vHi }, walkableDryNodes: nodes.length,
730	    supportHeightHistogram: (() => { const h: Record<string, number> = {}; for (const c of nodes) h[String(c.h)] = (h[String(c.h)] ?? 0) + 1; return h; })(),
731	    reliefNote: 'a single dominant support height means the arena corridor is the flat cube-face plateau: no terrain relief is available to occlude a level sightline', connectivity: '4-neighbour, |dh| <= maxSlopeCells (matches agentSurfaceNavigation NEIGHBORS)' },
732	  referenceCandidatesEvaluated: refCandidates.length,
733	  referenceRejections: refRejections,
734	  qualifyingSolutions: solutions.length,
735	  solution: best ? {
736	    fixedReference: { world: v3(best.reference.world), supportVoxel: [best.reference.u, best.reference.h, best.reference.v], socketHeight: REFERENCE_SOCKET, socketWorld: v3(socket(best.reference, REFERENCE_SOCKET).point), distanceToTree: r2(best.reference.world.distanceTo(tree.position)), referenceClearNodes: best.clearNodeCount },
737	    outerRoute: strip(best.outer),
738	    outerRouteWaypoints: best.outer._path.map(c => v3(c.world)),
739	    shorterRoute: strip(best.shorter),
740	    shorterRouteWaypoints: shortPath.map(c => v3(c.world)),
741	    intermediateWitnessCandidates: witnesses,
742	    savedWitnessRequirementIsDistinct: best.outer.witnessBlockedSamples === 0 && best.shorter.witnessBlockedSamples > 0
743	  } : null,
744	  solutionTable,
745	  terrainOccludedSolution: bestTerrain ? {
746	    fixedReference: { world: v3(bestTerrain.reference.world), supportVoxel: [bestTerrain.reference.u, bestTerrain.reference.h, bestTerrain.reference.v], socketHeight: REFERENCE_SOCKET, socketWorld: v3(socket(bestTerrain.reference, REFERENCE_SOCKET).point), distanceToTree: r2(bestTerrain.reference.world.distanceTo(tree.position)) },
747	    outerRoute: strip(bestTerrain.outer),
748	    outerRouteWaypoints: bestTerrain.outer._path.map(c => v3(c.world)),
749	    shorterRoute: strip(bestTerrain.shorter),
750	    intermediateWitnessCandidates: witnessesTerrain,
751	    plannerCrossValidation: { outerRouteEdges: validateEdges(bestTerrain.outer._path), outerRouteCornerLegs: validateCornerLegs(bestTerrain.outer._path) }
752	  } : null,
753	  witnessSearchRejections: witnessRejections,
754	  renderedCeilingCheck,
755	  alternateSolutions: solutions.slice(1, 5).map(s => ({
756	    fixedReference: v3(s.reference.world),
757	    outerLength: s.outer.walkedLength,
758	    outerSamples: s.outer.traceSampleCount,
759	    outerBlocked: s.outer.witnessBlockedSamples,
760	    shorterBlocked: s.shorter.witnessBlockedSamples
761	  })),
762	  socketSensitivity,
763	  plannerCrossValidation: best ? {
764	    outerRouteEdges: validateEdges(best.outer._path),
765	    outerRouteCornerLegs: validateCornerLegs(best.outer._path),
766	    shorterRouteEdges: validateEdges(shortPath),
767	    shorterRouteCornerLegs: validateCornerLegs(shortPath),
768	    rejectedCellSample: validateRejections()
769	  } : { shorterRouteEdges: validateEdges(shortPath), rejectedCellSample: validateRejections() },
770	  conventionDeltaVsPass1: conventionDelta(best),
771	  budgetBoundReached: best ? {
772	    outerWalkedLength: best.outer.walkedLength,
773	    outerTraceSamples: best.outer.traceSampleCount,
774	    lengthHeadroomUnits: r2(MAX_TRACE_LENGTH - best.outer.walkedLength),
775	    pointHeadroomSamples: MAX_TRACE_POINTS - best.outer.traceSampleCount,
776	    bindingBound: best.outer.traceSampleCount / MAX_TRACE_POINTS >= best.outer.walkedLength / MAX_TRACE_LENGTH ? 'points' : 'length'
777	  } : null,
778	  cpuSeconds: r2((Date.now() - t0) / 1000)
779	};
780	
781	process.stdout.write(JSON.stringify(report, null, 2) + '\n');
