  || (y.straight - x.straight)
  || (nodes[x.a].u - nodes[y.a].u) || (nodes[x.a].v - nodes[y.a].v)
  || (nodes[x.b].u - nodes[y.b].u) || (nodes[x.b].v - nodes[y.b].v));
