  .map((c, i) => ({ c, i }))
  .filter(x => trunkAllowed[x.i] && withinAnchor(x.c))
  .sort((p, q) => (p.c.world.distanceTo(pondAnchor) - q.c.world.distanceTo(pondAnchor)) || (p.c.u - q.c.u) || (p.c.v - q.c.v))
  .map(x => x.i);
