          // must then be supported from her actual standing position.
          const terraEndIdx = nodeIndex.get(`${Math.round(spanPts[spanPts.length - 1].x / VOXEL_SCALE)},${Math.round(spanPts[spanPts.length - 1].z / VOXEL_SCALE)}`);
