  const mask = new Uint8Array(nodes.length);
  const ref = nodes[refIdx];
  let covered = 0;
  for (let i = 0; i < nodes.length; i++) {
    if (!trunkAllowed[i]) continue;
    const s = support(nodes[i].world, ACTOR_SOCKET, ref, refSocketH, range);
