  },
  perRange: perRange.map(r => { const { _layouts, ...rest } = r as any; return rest; }),
  qualifyingLayoutsTotal: ranked.length,
  rankedLayouts: ranked.slice(0, 40).map((l, i) => ({ rank: i + 1, ...layoutReport(l, i < 2) })),
