  for (const ax of ['x', 'y', 'z'] as const) {
    const dd = dir[ax];
    if (dd === 0) continue;
    tDelta[ax] = Math.abs(VOXEL_SCALE / dd);
    const boundary = centres[ax] + (dd > 0 ? half : -half);
    tMax[ax] = (boundary - a[ax]) / dd;
