  const prev = new Int32Array(nodes.length).fill(-2);
  if (allowed && !allowed[fromIdx]) return prev;
  prev[fromIdx] = -1;
  const queue = [fromIdx];
  for (let qi = 0; qi < queue.length; qi++) {
    for (const nx of adjacency[queue[qi]]) {
