// ---------------------------------------------------------------------------
// Candidate endpoints (banks) and instrument positions
// ---------------------------------------------------------------------------
const withinAnchor = (c: Cell) => c.world.distanceTo(pondAnchor) <= ANCHOR_RADIUS;
const endpointCandidates = bankIdx.filter(i => withinAnchor(nodes[i]));

