    },
    shortRoute: {
      waypointCount: l.shortPath.length, walkedLength: r2(l.shortLength), traceSamples: l.shortSamples,
      withinLengthCap: l.shortLength <= MAX_TRACE_LENGTH, withinPointCap: l.shortSamples <= MAX_TRACE_POINTS,
