  if (terrain.isWaterVoxel(u, h, v)) return true;
  const scan = MAX_JETPACK_WATER_DEPTH_CELLS + WORKER_ROUTE_OPTIONS.clearanceCells;
  for (let lift = 1; lift <= scan; lift++) if (terrain.isWaterVoxel(u, h + lift, v)) return true;
