          let i = 0;
          while (i < m.samples.length) {
            if (headSup[i].supported || !heldSup[i].supported) { i++; continue; }
            let j = i;
            while (j + 1 < m.samples.length && !headSup[j + 1].supported && heldSup[j + 1].supported) j++;
