  const distance = a.distanceTo(rs.point);
  if (distance > range) {
    return { distance: r2(distance), inRange: false, clear: false, blockedBy: 'out-of-range', supported: false };
  }
  const l = los(a, rs.point, [...exemptAt(p), ...rs.exempt]);
