  while (queue.length) {
    const cur = queue.shift()!;
    const h = columnTop(cur.u, cur.v);
    let depth = 0;
    if (h !== null) { while (depth < 12 && terrain.isWaterVoxel(cur.u, h + depth + 1, cur.v)) depth++; }
    footprintCells.push({ u: cur.u, v: cur.v, depth });
