const footprintBounds = footprintCells.length ? {
  uLo: Math.min(...footprintCells.map(c => c.u)), uHi: Math.max(...footprintCells.map(c => c.u)),
  vLo: Math.min(...footprintCells.map(c => c.v)), vHi: Math.max(...footprintCells.map(c => c.v))
