    lo: { x: t.x - TRUNK_HALF - inflate, y: t.y - inflate, z: t.z - TRUNK_HALF - inflate },
    hi: { x: t.x + TRUNK_HALF + inflate, y: t.y + TRUNK_HEIGHT + inflate, z: t.z + TRUNK_HALF + inflate }
