}
function socket(cell: Cell, height: number) {
  return {
    point: cell.world.clone().addScaledVector(UP, height),
    exempt: [[cell.u, cell.h, cell.v], [cell.u, cell.h + 1, cell.v]] as Array<[number, number, number]>
