const FIELD_CELLS = 20; // 40 world units each way from the anchor column
const uLo = anchorCell.u - FIELD_CELLS, uHi = anchorCell.u + FIELD_CELLS;
const vLo = anchorCell.v - FIELD_CELLS, vHi = anchorCell.v + FIELD_CELLS;

const nodes: Cell[] = [];
